// Keep only posts worth an auto-draft. Returns one item per candidate (or none).
const cfg = $('Config').first().json;
const self = cfg.selfUserId;
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  if (!p || !p.id) continue;
  const author = (p.author && p.author.id) || p.user_id;
  if (author === self) continue;                 // skip your own posts
  const content = p.content || (p.metadata && p.metadata.content) || '';
  if (content.length < 30) continue;             // skip one-liners / announcements
  const created = new Date(p.createdAt || p.created_at);
  if (!isNaN(created) && (Date.now() - created.getTime())/60000 < 60) continue; // give humans 1h first
  out.push({ json: { id: p.id, title: p.title || (p.metadata && p.metadata.title) || '', content, authorFirst: (p.author && p.author.firstName) || '' } });
}
return out;

// Build the approval message for Telegram.
const post = $('Filter candidates').item.json;
const draft = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '(no draft)';
const slug = $('Config').first().json.groupSlug;
const url = `https://www.skool.com/${slug}?p=${(post.id||'').slice(0,8)}`;
const text = `📝 Unanswered post: *${post.title || '(no title)'}* by ${post.authorFirst}\n${url}\n\nDraft reply:\n${draft}\n\nReview, then post it from Skool (or extend this workflow with posts:createComment after approval).`;
return [{ json: { chatId: $('Config').first().json.telegramChatId, text } }];
